create extension vector;
create table items (
  id    int primary key,
  grupo smallint not null,
  emb   vector(128) not null);
-- los 10 más parecidos a una consulta, por distancia coseno:
select id from items order by emb <=> '[0.012,-0.093, …128 valores…]' limit 10;

lineas.c:
create index items_hnsw on items using hnsw (emb vector_cosine_ops);
explain (analyze, costs off, timing off, summary off)
select id from items order by emb <=> (select emb from items where id = 1) limit 10;
